import{_ as t,c as i,o as a,ag as n}from"./chunks/framework.CQuhCYrb.js";const u=JSON.parse('{"title":"Wifi","description":"","frontmatter":{"title":"Wifi"},"headers":[],"relativePath":"general/wifi.md","filePath":"general/wifi.md","lastUpdated":null}'),r={name:"general/wifi.md"};function s(o,e,l,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="wifi" tabindex="-1">Wifi <a class="header-anchor" href="#wifi" aria-label="Permalink to &quot;Wifi&quot;">​</a></h1><h2 id="wifi-1" tabindex="-1">Wifi <a class="header-anchor" href="#wifi-1" aria-label="Permalink to &quot;Wifi&quot;">​</a></h2><h3 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h3><p><strong>Wi-Fi</strong>, rumored on corners of the internet to be short for <em>Wireless Fidelity</em>, is a technology that allows devices to connect to a network wirelessly using the IEEE 802.11 standards. It enables laptops, smartphones, IoT devices, and countless other systems to exchange data over radio waves instead of physical cables. Operating primarily in the 2.4 GHz and 5 GHz bands—now extended to 6 GHz with Wi-Fi 6E—Wi-Fi is a cornerstone of modern digital communication, both in homes and in industrial, academic, and military environments.</p><h3 id="history-and-evolution-of-wi-fi-versions" tabindex="-1">History and Evolution of Wi-Fi Versions <a class="header-anchor" href="#history-and-evolution-of-wi-fi-versions" aria-label="Permalink to &quot;History and Evolution of Wi-Fi Versions&quot;">​</a></h3><p>Since its inception, Wi-Fi has evolved significantly in speed, range, and efficiency. The following table summarizes major iterations:</p><table tabindex="0"><thead><tr><th>Wi-Fi Version</th><th>IEEE Standard</th><th>Year</th><th>Max Speed</th><th>Key Features</th></tr></thead><tbody><tr><td>Wi-Fi 1</td><td>802.11b</td><td>1999</td><td>11 Mbps</td><td>First widely adopted standard</td></tr><tr><td>Wi-Fi 2</td><td>802.11a</td><td>1999</td><td>54 Mbps</td><td>Operated in 5 GHz band</td></tr><tr><td>Wi-Fi 3</td><td>802.11g</td><td>2003</td><td>54 Mbps</td><td>Backward-compatible with 802.11b</td></tr><tr><td>Wi-Fi 4</td><td>802.11n</td><td>2009</td><td>600 Mbps</td><td>MIMO (Multiple Input, Multiple Output)</td></tr><tr><td>Wi-Fi 5</td><td>802.11ac</td><td>2014</td><td>1.3+ Gbps</td><td>Beamforming, wider channels</td></tr><tr><td>Wi-Fi HaLow</td><td>802.11ah</td><td>2016</td><td>~347 Mbps</td><td>Sub-1 GHz, long-range IoT, similar to LoRa</td></tr><tr><td>Wi-Fi 6</td><td>802.11ax</td><td>2019</td><td>9.6 Gbps</td><td>OFDMA, MU-MIMO, Target Wake Time</td></tr><tr><td>Wi-Fi 6E</td><td>802.11ax (6 GHz)</td><td>2021</td><td>9.6 Gbps</td><td>Expansion to 6 GHz spectrum</td></tr><tr><td>Wi-Fi 7</td><td>802.11be</td><td>2024-2025</td><td>30+ Gbps</td><td>Extremely low latency, 320 MHz channels</td></tr></tbody></table><h3 id="wi-fi-as-a-signal-intelligence-vector" tabindex="-1">Wi-Fi as a Signal Intelligence Vector <a class="header-anchor" href="#wi-fi-as-a-signal-intelligence-vector" aria-label="Permalink to &quot;Wi-Fi as a Signal Intelligence Vector&quot;">​</a></h3><p>While Wi-Fi is best known for its utility, it is also a rich source of wireless signal intelligence. Every Wi-Fi-enabled device emits frames containing identifiers, signal strength, channel usage, and even hints of user behavior. Open-source tools, such as <strong>Aircrack-NG</strong> and <strong>Kismet Wireless</strong>, can passively intercept and analyze these emissions.</p><h3 id="aircrack-ng-and-wireless-surveying" tabindex="-1">Aircrack-NG and Wireless Surveying <a class="header-anchor" href="#aircrack-ng-and-wireless-surveying" aria-label="Permalink to &quot;Aircrack-NG and Wireless Surveying&quot;">​</a></h3><p>The <strong>Aircrack-NG suite</strong> is a powerful collection of open-source tools used for auditing Wi-Fi network security. At the heart of this toolkit is <strong>Airodump-NG</strong>, a packet capture utility tool that allows users to monitor all nearby wireless traffic while collecting critical metadata such as BSSIDs, ESSIDs, encryption types, and client association data. Airodump-NG can capture WPA2 four-way handshakes when clients connect to access points.</p><p>Once a handshake is captured, <strong>Aircrack-NG</strong> can be used to attempt to recover the pre-shared key (PSK) by executing dictionary-based or brute-force attacks against the encrypted credentials found in the <code>.pcap</code> file. This makes Aircrack-NG a foundational toolset in Wi-Fi penetration testing, especially for assessing the effectiveness of a network&#39;s Wi-Fi security settings an the strength of user-chosen passwords on WPA/WPA2 networks.</p><h3 id="kismet-wireless-overview" tabindex="-1">Kismet Wireless Overview <a class="header-anchor" href="#kismet-wireless-overview" aria-label="Permalink to &quot;Kismet Wireless Overview&quot;">​</a></h3><p><strong>Kismet</strong> is a robust, open-source wireless network detector, sniffer, and intrusion detection system. It supports most Wi-Fi cards capable of monitor mode and can work in both passive and active scanning modes. Kismet does not transmit packets by default, making it ideal for covert data collection and RF analysis.</p><p>Key Features:</p><ul><li><p>Capture of beacon, probe request, probe response, and data frames</p></li><li><p>Real-time detection of new devices and access points</p></li><li><p>Logging and replay capabilities in pcap and netxml formats</p></li><li><p>Integration with GPS for geolocation of detected networks and clients</p></li><li><p>Support for 802.11a/b/g/n/ac/ax, and 802.15/802.11-based SDR sniffing</p></li></ul><h3 id="capturing-wpa2-four-way-handshakes" tabindex="-1">Capturing WPA2 Four-Way Handshakes <a class="header-anchor" href="#capturing-wpa2-four-way-handshakes" aria-label="Permalink to &quot;Capturing WPA2 Four-Way Handshakes&quot;">​</a></h3><p>The WPA2-PSK (Wi-Fi Protected Access 2 - Pre-Shared Key) authentication model relies on a four-way handshake exchange between a client and access point. Using Airodump-NG (a tool of the Aircrack-NG suite), passive capture of a 4-way handshake and even the &quot;half handshake&quot; are possible - allowing that network&#39;s PSK to be cracked. Kismet can be configured to passively capture this handshake, a critical step in offline password cracking using tools like <code>hashcat</code> or <code>aircrack-ng</code>.</p><h3 id="steps-to-capture-a-handshake-using-kismet" tabindex="-1">Steps to Capture a Handshake Using Kismet <a class="header-anchor" href="#steps-to-capture-a-handshake-using-kismet" aria-label="Permalink to &quot;Steps to Capture a Handshake Using Kismet&quot;">​</a></h3><h2 id="enable-monitor-mode-on-a-compatible-wireless-card" tabindex="-1">Enable monitor mode on a compatible wireless card. <a class="header-anchor" href="#enable-monitor-mode-on-a-compatible-wireless-card" aria-label="Permalink to &quot;Enable monitor mode on a compatible wireless card.&quot;">​</a></h2><ol start="2"><li><p>Launch Kismet and configure it to use the desired interface and lock to the channel of targeted AP.</p></li><li><p>Wait for a client to connect to the target AP or force a reconnection (with external tools like <code>aireplay-ng</code>).</p></li><li><p>Kismet will automatically log the handshake when the client rejoins.</p></li><li><p>Extract the handshake from the Kismet logs (<code>.pcap</code> format) and analyze it with cracking tools.</p></li></ol><h3 id="wi-fi-direction-finding-and-target-tracking" tabindex="-1">Wi-Fi Direction Finding and Target Tracking <a class="header-anchor" href="#wi-fi-direction-finding-and-target-tracking" aria-label="Permalink to &quot;Wi-Fi Direction Finding and Target Tracking&quot;">​</a></h3><p>Each Wi-Fi device, whether an access point or a client, emits frames containing its MAC address and other metadata. These emissions serve as a unique digital signature, especially when randomized MAC features are disabled or circumvented.</p><p>With multiple antennas or mobile setups, Kismet (in conjunction with other tools such as <code>rtlamr</code>, <code>Yagi antennas</code>, or GPS) can be used to:</p><ul><li><p>Estimate signal strength and triangulate a source&#39;s location</p></li><li><p>Correlate devices across time and space using MAC address persistence</p></li><li><p>Track specific clients (e.g., mobile phones) through probe requests or known AP responses</p></li></ul><p>This kind of RF telemetry is often employed in:</p><ul><li><p>Penetration testing and red team operations</p></li><li><p>Crowd monitoring and de-anonymization research</p></li><li><p>Asset tracking in secure environments</p></li></ul><h3 id="ethical-and-legal-considerations" tabindex="-1">Ethical and Legal Considerations <a class="header-anchor" href="#ethical-and-legal-considerations" aria-label="Permalink to &quot;Ethical and Legal Considerations&quot;">​</a></h3><p>While tools like Kismet and Aircrack-NG are invaluable for legitimate security research and network diagnostics, unauthorized interception of wireless traffic may violate local or federal laws. Always ensure you have <strong>explicit authorization</strong> before engaging in wireless surveillance or traffic capture.</p><h3 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h3><p>Wi-Fi is more than a convenient way to access the internet—it is a constantly emitting RF signature that can be analyzed, mapped, and, under the right circumstances, exploited. Tools like Aircrack-NG and Kismet Wireless democratize access to this data, enabling defenders, researchers, and ethical hackers to better understand the RF landscape, secure networks, and conduct technical reconnaissance in a wireless-first world.</p><h3 id="disclaimer" tabindex="-1">Disclaimer <a class="header-anchor" href="#disclaimer" aria-label="Permalink to &quot;Disclaimer&quot;">​</a></h3><p>This wiki page is intended for educational and informational purposes only. All content, including guides, tools, and methodologies discussed herein, is provided with the explicit understanding that it will be used responsibly, ethically, and legally.</p><p>Unauthorized access, surveillance, or manipulation of networks, systems, or devices without proper consent is illegal and strictly condemned by the administrators of this wiki. We do not condone or support any activities that violate laws, terms of service, or the privacy of individuals or organizations.</p><p>Users are solely responsible for how they apply the knowledge found on this site. Always ensure you have clear permission before engaging in any form of network analysis, penetration testing, or signal monitoring. Use common sense, good judgment, and respect for legal boundaries at all times.</p><h3 id="external-links" tabindex="-1">External Links <a class="header-anchor" href="#external-links" aria-label="Permalink to &quot;External Links&quot;">​</a></h3><ul><li><p><a href="https://www.kismetwireless.net/" target="_blank" rel="noreferrer">Official Kismet Website</a></p></li><li><p><a href="https://github.com/kismetwireless/kismet" target="_blank" rel="noreferrer">Kismet GitHub Repository</a></p></li><li><p><a href="https://www.aircrack-ng.org/" target="_blank" rel="noreferrer">Official Aircrack-NG Website</a></p></li><li><p><a href="https://www.wi-fi.org/" target="_blank" rel="noreferrer">Wi-Fi Alliance</a></p></li></ul>',37)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
